db[5713]=db[5713] or {}
db[5713]["title#questit094"]={it="Un Colpo. Un Morto.",enHash={"020293f0"}}
db[6064]=db[6064] or {}
db[6064]["progress#questit094"]={it="Non preoccuparti, $Gragazzo:ragazza;! Potrai provarne qualcuno prima di doverti decidere per uno solo.",enHash={"4215137b"}}
db[6386]=db[6386] or {}
db[6386]["title#questit094"]={it="Torna al Crossroads",enHash={"ddfa3577"}}
db[7826]=db[7826] or {}
db[7826]["progress#questit094"]={it="Al momento accettiamo donazioni di wool cloth. Una donazione di sessanta pezzi di wool cloth ti farà guadagnare il pieno riconoscimento di Orgrimmar per il tuo gesto generoso. Con le scorte di wool che abbiamo, da te ci bastano sessanta pezzi in tutto: il resto dovremmo riuscire a procurarcelo da altri nel regno per portare avanti la raccolta.\n\nSe hai con te i sessanta pezzi di wool cloth e sei $Gpronto:pronta; a donarli, posso prenderli subito.",enHash={"00c482ca"}}
db[8155]=db[8155] or {}
db[8155]["title#questit094"]={it="Risorse di Arathi Basin!",enHash={"4cfb677e"}}
db[65593]=db[65593] or {}
db[65593]["objectives"]={it="Porta i cuori di Avelina Lilly e Isaac Pearson a Carendin Halgar, nel Temple of the Damned.",enHash={"b37f8db3"}}
db[65593]["progress"]={it="Ah, $N, eccoti di ritorno. Sei riuscit$Go:a; a procurarti i cuori degli amanti?",enHash={"86576246"}}
db[65593]["reward"]={it="Come previsto. Ottimo lavoro, $N.\n\n<Carendin tiene un cuore in ciascuna mano, poi li accosta delicatamente l'uno all'altro.>\n\nIdioti.",enHash={"6cc5fcfb"}}
db[65593]["text"]={it="Un incubo sarà attratto dai cuori degli amanti, e l'amore più struggente creerà l'esca più irresistibile.\n\nLe mie divinazioni me ne hanno indicati due che dovrebbero fare al caso nostro alla perfezione.\n\nNella Silverpine Forest, Avelina Lilly offre i suoi servigi di sarta ai maghi decaduti di Ambermill. Nei Barrens, Isaac Pearson spera di farsi un nome nella cittadina costiera di Ratchet.\n\nFaticano ai capi opposti del mondo, eppure i loro cuori si struggono soltanto l'uno per l'altra. Porta quei cuori a Carendin.",enHash={"33d24b86"}}
db[65593]["title"]={it="I Cuori degli Amanti",enHash={"d0c4efb8"}}
db[65597]=db[65597] or {}
db[65597]["objectives"]={it="Usando i Lovers' Hearts, evoca e sottometti un incubo, poi riporta i Lovers' Hearts a Carendin Halgar, nel Magic Quarter di Undercity.",enHash={"bc5521b9"}}
db[65597]["progress"]={it="L'incubo è abile nel combattimento, ma il suo fascino illusorio è la sua arma più potente. Basta un attimo di esitazione e il demone coglierà l'occasione per ammaliarti.\n\nNon permetterglielo, $N.",enHash={"36441e95"}}
db[65597]["reward"]={it="Notevole. Davvero notevole. I sayaad sono maestri nel fare dei mortali le loro prede. Più di uno stregone si è creduto abbastanza forte da comandarne uno, solo per ritrovarsi a sua volta comandato.\n\nQuesta prova non ti ha spezzato, $N, e con il tuo impegno ti sei guadagnat$Go:a; la ricompensa. Ti insegnerò l'incantesimo per evocare l'incubo.",enHash={"5c908ef0"}}
db[65597]["text"]={it="È finalmente giunto il momento. Porta i cuori al cerchio di evocazione qui sotto. Ponili al suo centro ed evoca l'incubo.\n\nIl demone non sarà contento quando si accorgerà che l'hai attirato in una trappola. Non cadere preda delle sue lusinghe, $N. Devi sottometterlo del tutto.\n\nSolo allora potrò insegnarti l'incantesimo per piegarlo alla tua volontà.",enHash={"fad5b57e"}}
db[65597]["title"]={it="Il Vincolo",enHash={"2a2909d6"}}
