db[78127]["progress"]={it="Hai portato qualcosa da aggiungere alla nostra collezione?",enHash={"5b88bdca"}}
db[78127]["reward"]={it="Grazie, $N. Il tuo impegno accresce il nostro sapere.\n\nSe scopri altre opere di magia che potrebbero giovare alla biblioteca, portamele, ti prego.",enHash={"28415be1"}}
