db[79007]=db[79007] or {}
db[79007]["reward"]={it="Ti imbatti nei resti dell'ennesimo cadavere carbonizzato, e il tuo sguardo cade su un messaggio fissato a un'asse di legno.",enHash={"b5172652"}}
db[79007]["text"]={it="<Mentre il debole bagliore delle braci si spegne, ti imbatti nei resti di un fuoco recente.\n\nTra le provviste sparse, scopri un biglietto raggrinzito dal calore.>\n\n\"Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo.\"",enHash={"ccc8e1c5"}}
db[79008]=db[79008] or {}
db[79008]["objectives"]={it="I resti carbonizzati del biglietto sono la tua unica guida.",enHash={"764654e2"}}
db[79008]["reward"]={it="Ti imbatti nei resti dell'ennesimo cadavere carbonizzato, e il tuo sguardo cade su un messaggio fissato a un'asse di legno.",enHash={"b5172652"}}
db[79008]["text"]={it="<Mentre il debole bagliore delle braci si spegne, ti imbatti nei resti di un fuoco recente.\n\nTra le provviste sparse, scopri un biglietto raggrinzito dal calore.>\n\n\"Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo.\"",enHash={"ccc8e1c5"}}
